bad_example:
function schedule(value: string | null) {
  if (value !== null) {
    setTimeout(() => {
      console.log(value.toUpperCase()); // error: value es 'string | null' aca
    }, 100);
  }
}

good_example:
function schedule(value: string | null) {
  if (value !== null) {
    const narrowed = value;
    setTimeout(() => {
      console.log(narrowed.toUpperCase()); // ok, narrowed es 'string' y no puede reasignarse
    }, 100);
  }
}
